					assertThat(records.fill(batch, 0)).isZero();
					assertThat(records.seekForward(target[0], target[1], target[2], target[3])).isTrue();
					assertThat(records.fill(batch, 2)).isEqualTo(1);
					assertThat(java.util.Arrays.copyOf(batch, 4)).containsExactly(target);
					assertThat(records.fill(batch, 2)).isZero();
